function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // garlic clove
  ctx.fillStyle = 'white';
  ctx.beginPath();
  ctx.arc(W/2, H/2, 50, 0, 2 * Math.PI);
  ctx.fill();
  ctx.stroke();

  // immune cells
  for (let i = 0; i < 5; i++) {
    ctx.fillStyle = 'white';
    ctx.beginPath();
    ctx.arc(W/2 + Math.cos(t + i) * 100, H/2 + Math.sin(t + i) * 100, 10, 0, 2 * Math.PI);
    ctx.fill();
    ctx.stroke();

    // cell movement
    ctx.beginPath();
    ctx.moveTo(W/2 + Math.cos(t + i) * 100, H/2 + Math.sin(t + i) * 100);
    ctx.lineTo(W/2 + Math.cos(t + i) * 100 + Math.cos(t + i) * 10, H/2 + Math.sin(t + i) * 100 + Math.sin(t + i) * 10);
    ctx.stroke();
  }

  // stick figure
  ctx.fillStyle = 'white';
  ctx.beginPath();
  ctx.arc(W/2, H/2 + 70, 10, 0, 2 * Math.PI);
  ctx.fill();
  ctx.stroke();

  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 70);
  ctx.lineTo(W/2, H/2 + 100);
  ctx.stroke();

  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 90);
  ctx.lineTo(W/2 - 20, H/2 + 120);
  ctx.stroke();

  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 90);
  ctx.lineTo(W/2 + 20, H/2 + 120);
  ctx.stroke();

  ctx.restore();
}
